import { readFileSync, realpathSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const STATES = new Set(['pending', 'succeeded', 'failed']);

function requireNonemptyString(value) {
  if (typeof value !== 'string' || value.length === 0) {
    throw new Error('expected a nonempty string');
  }
  return value;
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) {
    throw new Error('spec must be an array of job objects');
  }
  const jobs = new Map();
  for (const entry of spec) {
    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
      throw new Error('each job must be a plain object');
    }
    const id = requireNonemptyString(entry.id);
    if (jobs.has(id)) {
      throw new Error(`duplicate job id: ${id}`);
    }
    const deps = entry.deps;
    if (!Array.isArray(deps)) {
      throw new Error(`job "${id}": deps must be an array`);
    }
    const seenDeps = new Set();
    for (const dep of deps) {
      const depId = requireNonemptyString(dep);
      if (seenDeps.has(depId)) {
        throw new Error(`job "${id}": duplicate dependency: ${depId}`);
      }
      seenDeps.add(depId);
    }
    const state = entry.state;
    if (typeof state !== 'string' || !STATES.has(state)) {
      throw new Error(`job "${id}": state must be "pending", "succeeded", or "failed"`);
    }
    jobs.set(id, { id, deps, state });
  }
  for (const [id, job] of jobs) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) {
        throw new Error(`job "${id}": unknown dependency: ${dep}`);
      }
    }
  }

  const indegree = new Map();
  const children = new Map();
  for (const [id, job] of jobs) {
    indegree.set(id, job.deps.length);
    for (const dep of job.deps) {
      const list = children.get(dep) ?? [];
      list.push(id);
      children.set(dep, list);
    }
  }

  const zero = new Set();
  for (const [id, degree] of indegree) {
    if (degree === 0) zero.add(id);
  }
  const topo = [];
  while (zero.size > 0) {
    let next = null;
    for (const id of zero) {
      if (next === null || id < next) next = id;
    }
    zero.delete(next);
    topo.push(next);
    for (const child of children.get(next) ?? []) {
      const degree = indegree.get(child) - 1;
      indegree.set(child, degree);
      if (degree === 0) zero.add(child);
    }
  }
  if (topo.length !== jobs.size) {
    throw new Error('dependency cycle detected');
  }

  const ancestors = new Map();
  for (const id of topo) {
    const set = new Set();
    for (const dep of jobs.get(id).deps) {
      set.add(dep);
      for (const ancestor of ancestors.get(dep)) set.add(ancestor);
    }
    ancestors.set(id, set);
  }

  const blocked = [];
  for (const [id, job] of jobs) {
    if (job.state !== 'pending') continue;
    const causes = [];
    for (const ancestor of ancestors.get(id)) {
      if (jobs.get(ancestor).state === 'failed') causes.push(ancestor);
    }
    if (causes.length > 0) {
      causes.sort();
      blocked.push({ id, causes });
    }
  }
  blocked.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  const blockedIds = new Set(blocked.map((entry) => entry.id));

  const order = topo.filter((id) => {
    const job = jobs.get(id);
    return job.state === 'pending' && !blockedIds.has(id);
  });

  const ready = [];
  for (const [id, job] of jobs) {
    if (job.state !== 'pending' || blockedIds.has(id)) continue;
    if (job.deps.every((dep) => jobs.get(dep).state === 'succeeded')) {
      ready.push(id);
    }
  }
  ready.sort();

  return { order, ready, blocked };
}

function isMainModule() {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return realpathSync(entry) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

if (isMainModule()) {
  const args = process.argv.slice(2);
  try {
    if (args.length !== 1) {
      throw new Error('usage: node job-plan.js SPECFILE');
    }
    const spec = JSON.parse(readFileSync(args[0], 'utf8'));
    process.stdout.write(`${JSON.stringify(planJobs(spec))}\n`);
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('duplicate ids, duplicate deps, and malformed fields throw', () => {
  assert.throws(() => planJobs([job('a'), job('a')]));
  assert.throws(() => planJobs([job('a', ['b', 'b'])]));
  assert.throws(() => planJobs([job('a', ['a'])]));
  assert.throws(() => planJobs([job('a', [], 'bogus')]));
  assert.throws(() => planJobs([job('a', 'nope')]));
  assert.throws(() => planJobs([{ id: 'a', state: 'pending' }]));
  assert.throws(() => planJobs([{ deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([job('', [])]));
  assert.throws(() => planJobs([job('a', [''])]));
  assert.throws(() => planJobs([job(42, [])]));
  assert.throws(() => planJobs([job('a', [5])]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs([[]]));
  assert.throws(() => planJobs(null));
  assert.throws(() => planJobs('nope'));
});

test('cycles are detected over the entire graph, including completed jobs', () => {
  assert.throws(() => planJobs([job('a', ['b'], 'succeeded'), job('b', ['a'], 'succeeded')]));
  assert.throws(() => planJobs([job('a', ['b'], 'failed'), job('b', ['a'], 'failed')]));
  assert.throws(() =>
    planJobs([
      job('a', ['b'], 'succeeded'),
      job('b', ['c'], 'failed'),
      job('c', ['a'], 'succeeded'),
      job('d'),
    ]),
  );
});

test('__proto__ and constructor are ordinary ids', () => {
  const spec = [job('__proto__'), job('constructor', ['__proto__'])];
  assert.deepEqual(planJobs(spec), {
    order: ['__proto__', 'constructor'],
    ready: ['__proto__'],
    blocked: [],
  });
  assert.equal(Object.getPrototypeOf(spec[0]), Object.prototype);
});

test('input is not mutated and unknown fields are ignored', () => {
  const spec = [job('b', [], 'pending'), job('a', ['b'], 'pending')];
  spec[0].extra = 'ignore me';
  spec[1].nested = { deeply: true };
  const copy = structuredClone(spec);
  const plan = planJobs(spec);
  assert.deepEqual(spec, copy);
  assert.deepEqual(plan, { order: ['b', 'a'], ready: ['b'], blocked: [] });
  assert.deepEqual(Object.keys(plan), ['order', 'ready', 'blocked']);
});

test('order follows the full graph topology, not the pending-only graph', () => {
  assert.deepEqual(
    planJobs([job('a', ['z']), job('b'), job('z', [], 'succeeded')]),
    { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] },
  );
});

test('failed ancestry is transitive through succeeded and failed jobs', () => {
  assert.deepEqual(
    planJobs([
      job('f1', [], 'failed'),
      job('s', ['f1'], 'succeeded'),
      job('p', ['s']),
      job('f2', ['f1']),
      job('f3', ['f2']),
    ]),
    {
      order: [],
      ready: [],
      blocked: [
        { id: 'f2', causes: ['f1'] },
        { id: 'f3', causes: ['f1'] },
        { id: 'p', causes: ['f1'] },
      ],
    },
  );
});

test('causes are unique and sorted, blocked sorted by id', () => {
  assert.deepEqual(
    planJobs([
      job('f2', [], 'failed'),
      job('f1', [], 'failed'),
      job('p', ['f2', 'f1']),
      job('q', ['p']),
    ]),
    {
      order: [],
      ready: [],
      blocked: [
        { id: 'p', causes: ['f1', 'f2'] },
        { id: 'q', causes: ['f1', 'f2'] },
      ],
    },
  );
});

test('ids preserve whitespace and unicode; ordering is by code units', () => {
  assert.deepEqual(
    planJobs([job('a b'), job(' b', ['a b']), job('z'), job('Ü')]),
    {
      order: ['a b', ' b', 'z', 'Ü'],
      ready: ['a b', 'z', 'Ü'],
      blocked: [],
    },
  );
});

test('blocked pending jobs stay out of order and ready; ready ignores pending deps', () => {
  assert.deepEqual(
    planJobs([
      job('boom', [], 'failed'),
      job('waiter', ['boom']),
      job('later', ['waiter']),
      job('solo'),
    ]),
    {
      order: ['solo'],
      ready: ['solo'],
      blocked: [
        { id: 'later', causes: ['boom'] },
        { id: 'waiter', causes: ['boom'] },
      ],
    },
  );
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { planJobs } from '../job-plan.js';

const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));

function run(args) {
  return spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
}

test('importing the module does not run the CLI', async () => {
  const mod = await import('../job-plan.js');
  assert.equal(typeof mod.planJobs, 'function');
  assert.deepEqual(planJobs([]), { order: [], ready: [], blocked: [] });
});

test('cli prints only the plan as JSON plus newline and exits 0', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const file = join(dir, 'spec.json');
  writeFileSync(file, JSON.stringify([{ id: 'b' }, { id: 'a', deps: ['b'], state: 'pending' }]));
  const result = run([file]);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  const expected = JSON.stringify({ order: ['b', 'a'], ready: ['b'], blocked: [] });
  assert.equal(result.stdout, `${expected}\n`);
  assert.deepEqual(JSON.parse(result.stdout), { order: ['b', 'a'], ready: ['b'], blocked: [] });
});

test('cli exits 2 with nonempty stderr and no stdout on invalid input', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const invalidJson = join(dir, 'invalid.json');
  writeFileSync(invalidJson, '{nope');
  const notArray = join(dir, 'not-array.json');
  writeFileSync(notArray, JSON.stringify({ id: 'a' }));
  const cycle = join(dir, 'cycle.json');
  writeFileSync(
    cycle,
    JSON.stringify([
      { id: 'a', deps: ['b'], state: 'pending' },
      { id: 'b', deps: ['a'], state: 'pending' },
    ]),
  );
  const missing = join(dir, 'missing.json');
  for (const args of [[], [invalidJson, 'extra'], [invalidJson], [notArray], [cycle], [missing]]) {
    const result = run(args);
    assert.equal(result.status, 2, `args=${JSON.stringify(args)}`);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0, `stderr empty for args=${JSON.stringify(args)}`);
  }
});

