  const file = join(dir, 'spec.json');
  writeFileSync(file, JSON.stringify([{ id: 'b', deps: [], state: 'pending' }, { id: 'a', deps: ['b'], state: 'pending' }]));
  const result = run([file]);
  assert.equal(result.status, 0);
  assert.equal(result.stderr, '');
  const expected = JSON.stringify({ order: ['b', 'a'], ready: ['b'], blocked: [] });
  assert.equal(result.stdout, `${expected}\n`);
  assert.deepEqual(JSON.parse(result.stdout), { order: ['b', 'a'], ready: ['b'], blocked: [] });
});

test('cli exits 2 with nonempty stderr and no stdout on invalid input', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const invalidJson = join(dir, 'invalid.json');
  writeFileSync(invalidJson, '{nope');
  const notArray = join(dir, 'not-array.json');
  writeFileSync(notArray, JSON.stringify({ id: 'a' }));
  const cycle = join(dir, 'cycle.json');
  writeFileSync(
    cycle,
    JSON.stringify([
      { id: 'a', deps: ['b'], state: 'pending' },
      { id: 'b', deps: ['a'], state: 'pending' },
    ]),
  );
  const missing = join(dir, 'missing.json');
  for (const args of [[], [invalidJson, 'extra'], [invalidJson], [notArray], [cycle], [missing]]) {
    const result = run(args);
    assert.equal(result.status, 2, `args=${JSON.stringify(args)}`);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0, `stderr empty for args=${JSON.stringify(args)}`);
  }
});

