import test from 'node:test';
import assert from 'node:assert/strict';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('duplicate ids, duplicate deps, and malformed fields throw', () => {
  assert.throws(() => planJobs([job('a'), job('a')]));
  assert.throws(() => planJobs([job('a', ['b', 'b'])]));
  assert.throws(() => planJobs([job('a', ['a'])]));
  assert.throws(() => planJobs([job('a', [], 'bogus')]));
  assert.throws(() => planJobs([job('a', 'nope')]));
  assert.throws(() => planJobs([{ id: 'a', state: 'pending' }]));
  assert.throws(() => planJobs([{ deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([job('', [])]));
  assert.throws(() => planJobs([job('a', [''])]));
  assert.throws(() => planJobs([job(42, [])]));
  assert.throws(() => planJobs([job('a', [5])]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs([[]]));
  assert.throws(() => planJobs(null));
  assert.throws(() => planJobs('nope'));
});

test('cycles are detected over the entire graph, including completed jobs', () => {
  assert.throws(() => planJobs([job('a', ['b'], 'succeeded'), job('b', ['a'], 'succeeded')]));
  assert.throws(() => planJobs([job('a', ['b'], 'failed'), job('b', ['a'], 'failed')]));
  assert.throws(() =>
    planJobs([
      job('a', ['b'], 'succeeded'),
      job('b', ['c'], 'failed'),
      job('c', ['a'], 'succeeded'),
      job('d'),
    ]),
  );
});

test('__proto__ and constructor are ordinary ids', () => {
  const spec = [job('__proto__'), job('constructor', ['__proto__'])];
  assert.deepEqual(planJobs(spec), {
    order: ['__proto__', 'constructor'],
    ready: ['__proto__'],
    blocked: [],
  });
  assert.equal(Object.getPrototypeOf(spec[0]), Object.prototype);
});

test('input is not mutated and unknown fields are ignored', () => {
  const spec = [job('b', [], 'pending'), job('a', ['b'], 'pending')];
  spec[0].extra = 'ignore me';
  spec[1].nested = { deeply: true };
  const copy = structuredClone(spec);
  const plan = planJobs(spec);
  assert.deepEqual(spec, copy);
  assert.deepEqual(plan, { order: ['b', 'a'], ready: ['b'], blocked: [] });
  assert.deepEqual(Object.keys(plan), ['order', 'ready', 'blocked']);
});

test('order follows the full graph topology, not the pending-only graph', () => {
  assert.deepEqual(
    planJobs([job('a', ['z']), job('b'), job('z', [], 'succeeded')]),
    { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] },
  );
});

test('failed ancestry is transitive through succeeded and failed jobs', () => {
  assert.deepEqual(
    planJobs([
      job('f1', [], 'failed'),
      job('s', ['f1'], 'succeeded'),
      job('p', ['s']),
      job('f2', ['f1']),
      job('f3', ['f2']),
    ]),
    {
      order: [],
      ready: [],
      blocked: [
        { id: 'f2', causes: ['f1'] },
        { id: 'f3', causes: ['f1'] },
        { id: 'p', causes: ['f1'] },
      ],
    },
  );
});

test('causes are unique and sorted, blocked sorted by id', () => {
  assert.deepEqual(
    planJobs([
      job('f2', [], 'failed'),
      job('f1', [], 'failed'),
      job('p', ['f2', 'f1']),
      job('q', ['p']),
    ]),
    {
      order: [],
      ready: [],
      blocked: [
        { id: 'p', causes: ['f1', 'f2'] },
        { id: 'q', causes: ['f1', 'f2'] },
      ],
    },
  );
});

test('ids preserve whitespace and unicode; ordering is by code units', () => {
  assert.deepEqual(
    planJobs([job('a b'), job(' b', ['a b']), job('z'), job('Ü')]),
    {
      order: ['a b', ' b', 'z', 'Ü'],
      ready: ['a b', 'z', 'Ü'],
      blocked: [],
    },
  );
});

test('blocked pending jobs stay out of order and ready; ready ignores pending deps', () => {
  assert.deepEqual(
    planJobs([
      job('boom', [], 'failed'),
      job('waiter', ['boom']),
      job('later', ['waiter']),
      job('solo'),
    ]),
    {
      order: ['solo'],
      ready: ['solo'],
      blocked: [
        { id: 'later', causes: ['boom'] },
        { id: 'waiter', causes: ['boom'] },
      ],
    },
  );
});

